// Casamento mantém o texto original; os outros nichos recebem saudação + pergunta adaptada ao nicho (nó "Gerar Pergunta de Dor (IA)").
// APRESENTAR: true inclui "Aqui é o Hamilton, da Agência OnlineAgora." na abertura; false = só saudação + pergunta.
const APRESENTAR = false;

// --- Saudação por horário ---
function saudacaoPorHorario(hora) {
  if (hora >= 5 && hora < 12) return 'Bom dia';
  if (hora >= 12 && hora < 18) return 'Boa tarde';
  return 'Boa noite';
}
const horaBR = new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false });
const saudacaoBase = saudacaoPorHorario(parseInt(horaBR, 10));

const negocio = String($json.negocio || $json.nome || '').trim();
const nicho = String($json.nicho || '').trim();
const primeiroNome = String($json.nome || '').trim().split(' ')[0] || '';

let telefoneNormalizado = String($json.telefone_normalizado || '').replace(/\D/g, '');
if (telefoneNormalizado && !telefoneNormalizado.startsWith('55')) {
  telefoneNormalizado = '55' + telefoneNormalizado;
}

const ehCasamento = /casament|noiva|cerimonial|wedding/i.test(nicho);

let variante;
let mensagemEnviada;

if (ehCasamento) {
  // texto atual, sem mudança
  variante = 'CASAMENTO_B';
  mensagemEnviada = `${saudacaoBase}! Tudo bem? Uma dúvida rápida: a agenda de vocês${negocio ? ` (${negocio})` : ''} está cheia pros próximos meses ou ainda tem espaço pra novas noivas? Trabalho com isso e queria te contar uma ideia.`;
} else {
  // nicho: a pergunta vem do nó "Gerar Pergunta de Dor (IA)"; o fallback não usa artigo (o nicho vem como "Farmácia de Manipulação", "Pilates"...)
  const pergunta = String($json.pergunta_variante_a || '').trim()
    || 'Algum dos clientes que pedem orçamento pelo WhatsApp costuma sumir depois, sem responder?';
  // o nome vem do Google Maps (é o nome do negócio), então não dá pra tratar como primeiro nome de pessoa
  // e vem com texto de SEO ("Biovit Farma I Farmácia de Manipulação I ... Centro, Diadema"): fica só com o primeiro pedaço
  let nomeCurto = negocio.split(/\s+[|•–—-]\s+|\s+I\s+|,\s+/)[0].trim();
  if (nomeCurto.length < 2) nomeCurto = negocio;
  if (nomeCurto.length > 45) nomeCurto = nomeCurto.slice(0, 45).replace(/\s+\S*$/, '');
  const ehPessoa = /^dra?\.?\s/i.test(nomeCurto);
  const saudacao = !nomeCurto ? `${saudacaoBase}!` : (ehPessoa ? `${saudacaoBase}, ${nomeCurto}!` : `${saudacaoBase}, equipe ${nomeCurto}!`);
  const abertura = APRESENTAR ? `${saudacao} Aqui é o Hamilton, da Agência OnlineAgora.` : saudacao;
  variante = 'NICHO_A';
  // linha em branco antes da pergunta: é o formato que o WF01b lê pra montar a mensagem B
  mensagemEnviada = `${abertura}\n\n${pergunta}`;
}

const baseHash = `${telefoneNormalizado}|${mensagemEnviada}`;
let hash = 0;
for (let i = 0; i < baseHash.length; i++) {
  hash = ((hash << 5) - hash) + baseHash.charCodeAt(i);
  hash |= 0;
}
const mensagem1Hash = Math.abs(hash).toString(16);

return {
  json: {
    ...$json,
    primeiro_nome: primeiroNome,
    telefone_normalizado: telefoneNormalizado,
    whatsapp_number: telefoneNormalizado,
    mensagem_enviada: mensagemEnviada,
    mensagem_base: mensagemEnviada,
    variante_mensagem: variante,
    mensagem1_hash: mensagem1Hash
  }
};

const lead = $('Limitar Lote').item.json;
const nicho = String(lead.nicho || '').trim();
const negocio = String(lead.negocio || '').trim();
const aiContent = $json.choices?.[0]?.message?.content || '';

let perguntaA = '';
let perguntaB = '';

try {
  const jsonMatch = aiContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    perguntaA = parsed.varianteA || '';
    perguntaB = parsed.varianteB || '';
  }
} catch(e) {
  perguntaA = aiContent.trim();
  perguntaB = aiContent.trim();
}

// Fallbacks genéricos por nicho se a IA falhar ou não tiver dados
const fallbackA = 'Algum dos clientes que pedem orçamento pelo WhatsApp costuma sumir depois, sem responder?';
const fallbackB = 'Às vezes chega mensagem fora do horário e fica esperando até o dia seguinte por aí?';

if (!perguntaA) perguntaA = fallbackA;
if (!perguntaB) perguntaB = fallbackB;

return {
  json: {
    ...lead,
    pergunta_variante_a: perguntaA,
    pergunta_variante_b: perguntaB
  }
};

const agora = new Date();
const delaysMinutos = [1, 2, 3, 4, 5];
const intervaloMinutos = delaysMinutos[Math.floor(Math.random() * delaysMinutos.length)];
const delaySegundos = intervaloMinutos * 60;

return {
  json: {
    ...$json,
    delay_segundos: delaySegundos,
    intervalo_minutos: intervaloMinutos,
    reservado_em: agora.toISOString()
  }
};

// ===== Horário GMN: decide se o lead pode receber a 1ª mensagem agora (BRT) =====
const GMN = (() => {
  const W = 10080; // minutos na semana
  const agoraBRT = () => { const d = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })); return { dow: d.getDay(), min: d.getHours() * 60 + d.getMinutes() }; };
  const periodos = (h) => (h && Array.isArray(h.periods)) ? h.periods : [];
  const pm = (x) => (x.day || 0) * 1440 + (x.hour || 0) * 60 + (x.minute || 0);
  // aberto num minuto da semana (domingo 00:00 = 0, igual ao Places)
  const aberto = (h, w) => { w = ((w % W) + W) % W; return periodos(h).some(p => { if (!p.open) return false; if (!p.close) return true; const o = pm(p.open); let c = pm(p.close); if (c <= o) c += W; return (w >= o && w < c) || (w + W >= o && w + W < c); }); };
  // fallback sem horário do GMN: nichos que classicamente só abrem à noite
  const NICHO_NOITE = /pizz|hamb[uú]rg|burger|\bbar\b|\bbares\b|choperia|boteco|\bpub\b|petiscaria|esfiharia/i;
  const decidir = (j, agora) => {
    const { dow, min } = agora || agoraBRT();
    const w = dow * 1440 + min;
    const dia = (min >= 540 && min < 710) || (min >= 840 && min < 1070); // 9h-11h50 e 14h-17h50
    const noite = min >= 1080 && min < 1170; // 18h-19h30, só para negócio noturno
    const janela = dia ? 'dia' : (noite ? 'noite' : 'fora');
    const h = j.horario_gmn;
    if (periodos(h).length > 0) {
      const noturno = !aberto(h, dow * 1440 + 900) && aberto(h, dow * 1440 + 1140); // fechado 15h e aberto 19h, hoje
      const abertoAgora = aberto(h, w) && aberto(h, w + 45); // aberto agora e por mais 45 min
      if (janela === 'fora') return { ok: false, janela, motivo: 'fora_da_janela', noturno, fonte: 'gmn' };
      if (janela === 'noite' && !noturno) return { ok: false, janela, motivo: 'nao_noturno', noturno, fonte: 'gmn' };
      return { ok: abertoAgora, janela, motivo: abertoAgora ? 'aberto_agora_gmn' : 'fechado_agora_gmn', noturno, fonte: 'gmn' };
    }
    // sem horário (ainda não buscado, ou o GMN não informa): decide pelo nicho
    const noturno = NICHO_NOITE.test(String(j.nicho || '') + ' ' + String(j.negocio || ''));
    const fonte = (h && h.buscado_em) ? 'nicho_gmn_sem_horario' : 'nicho_nao_buscado';
    if (janela === 'fora') return { ok: false, janela, motivo: 'fora_da_janela', noturno, fonte };
    if (janela === 'dia') return { ok: !noturno, janela, motivo: noturno ? 'nicho_noturno_de_dia' : 'nicho_diurno', noturno, fonte };
    return { ok: noturno, janela, motivo: noturno ? 'nicho_noturno_a_noite' : 'nao_noturno', noturno, fonte };
  };
  return { decidir };
})();
// ===== fim Horário GMN =====

const saida = items.map(item => {
  const j = item.json;

  const status = String(j.status || '').trim();
  const telefone = String(j.telefone_normalizado || '').replace(/\D/g, '');

  const truthy = (v) => ['true','sim','yes','1'].includes(String(v || '').trim().toLowerCase());
  const hasValue = (v) => String(v ?? '').trim() !== '';

  const bloqueios = [];

  if (/cart[oó]rio/i.test(String(j.nicho || ''))) bloqueios.push(`nicho_excluido=${j.nicho || ''}`);

  // horário de funcionamento (GMN) ou, sem ele, nicho: pizzaria de tarde cai no automático
  const gmn = GMN.decidir(j);
  if (!gmn.ok) bloqueios.push(`horario=${gmn.motivo}`);

  if (status !== '' && status !== 'erro_envio_whatsapp') bloqueios.push(`status=${status}`);

  if (!/^55[0-9]{10,11}$/.test(telefone)) bloqueios.push(`telefone_invalido=${telefone}`);

  if (truthy(j.mensagem_enviada)) bloqueios.push('mensagem_enviada');
  if (truthy(j.bloqueado_wf01)) bloqueios.push('bloqueado_wf01');
  if (hasValue(j.mensagem1_enviada_em)) bloqueios.push(`mensagem1_enviada_em=${j.mensagem1_enviada_em}`);
  if (hasValue(j.mensagem1_id)) bloqueios.push(`mensagem1_id=${j.mensagem1_id}`);
  if (hasValue(j.reservado_em)) bloqueios.push(`reservado_em=${j.reservado_em}`);
  if (hasValue(j.processando_em)) bloqueios.push(`processando_em=${j.processando_em}`);

  return {
    json: {
      ...j,
      telefone_limpo_debug: telefone,
      elegivel_wf01: bloqueios.length === 0,
      motivo_bloqueio_wf01: bloqueios.join(' | ')
    }
  };
});
// Prioridade da fila: assessoria/cerimonial com celular > outros com celular > assessoria com fixo > outros com fixo; dentro de cada grupo, mais avaliações primeiro
const ehAssessoria = (j) => /assess|cerimon/i.test(String(j.nome || '') + ' ' + String(j.negocio || ''));
const ehCelular = (j) => /^55[0-9]{2}9[0-9]{8}$/.test(String(j.telefone_limpo_debug || ''));
const grupo = (j) => (ehCelular(j) ? 0 : 2) + (ehAssessoria(j) ? 0 : 1);
// Região prioritária: São Paulo (capital) e Grande ABC. Chave = grupo*2 + região: assessoria+celular em SP/ABC > assessoria+celular em outras cidades > demais com celular em SP/ABC > ...
const ehRegiaoPrioritaria = (j) => /s[aã]o paulo|santo andr[eé]|s[aã]o bernardo|s[aã]o caetano|diadema|mau[aá]|ribeir[aã]o pires|rio grande da serra/i.test(String(j.cidade || ''));
const chave = (j) => grupo(j) * 2 + (ehRegiaoPrioritaria(j) ? 0 : 1);
return saida.sort((a, b) => (chave(a.json) - chave(b.json)) || ((Number(b.json.avaliacoes) || 0) - (Number(a.json.avaliacoes) || 0)));

const msgs = items.map(i => i.json).filter(m => m && m.body);
const lead = $('Aguardar Delay Humano').item.json;
const envioTs = (() => {
  const v = $('Atualizar Enviado + Trava Permanente WF01 (CRM)').item.json?.custom_fields?.wf01?.mensagem1_enviada_em;
  if (v) { const d = new Date(v); if (!isNaN(d.getTime())) return d.getTime(); }
  return Date.now() - 70000;
})();

const respostas = msgs.filter(m => {
  const ts = m.created_at ? new Date(m.created_at).getTime() : 0;
  return ts >= envioTs - 5000;
});

const textos = respostas.map(m => String(m.body || '').toLowerCase()).join(' ');

const keywords = [
  'automátic', 'automat', 'bot ', 'robô', 'robo ',
  'fora do horário', 'fora de horario',
  'não estamos disponíveis', 'nao estamos disponiveis',
  'obrigado por entrar em contato', 'sua mensagem foi recebida',
  'retornaremos em breve', 'em breve retornaremos',
  'atendimento automatizado', 'atendimento via whatsapp',
  'horário de atendimento', 'horario de atendimento',
  'digite 1', 'pressione 1', 'opção 1', 'opcao 1'
];

const padraoRobo = keywords.some(k => textos.includes(k));

const ultraRapida = respostas.some(m => {
  const ts = m.created_at ? new Date(m.created_at).getTime() : 0;
  return ts > 0 && (ts - envioTs) < 8000 && ts > envioTs;
});

const roboDetectado = padraoRobo || ultraRapida;

return [{
  json: {
    ...lead,
    robo_detectado: roboDetectado,
    robo_motivo: padraoRobo ? 'padrao_texto' : (ultraRapida ? 'resposta_ultra_rapida' : 'nao_detectado'),
    robo_texto_resposta: textos.substring(0, 300),
    robo_qtd_respostas: respostas.length
  }
}];

// Quando Enviar WhatsApp falha com 400, $json vira o objeto de erro sem row_number.
// Recuperamos os dados da lead de 'Preparar Mensagem' que rodou antes do erro.
const lead = $('Preparar Mensagem').item.json;
return {
  json: {
    row_number: lead.row_number,
    telefone_normalizado: lead.telefone_normalizado || lead.whatsapp_number || '',
    negocio: lead.negocio || '',
    nome: lead.nome || ''
  }
};

const lead = $json;
const c = lead.contacts || {};
const meta = c.source_metadata || {};
const cf = lead.custom_fields || {};
const wf01 = cf.wf01 || {};

let telNorm = String(c.phone_number || '').replace(/\D/g, '');
if (telNorm && !telNorm.startsWith('55')) telNorm = '55' + telNorm;

return {
  json: {
    row_number: lead.id,
    lead_id: lead.id,
    contact_id: lead.contact_id,
    nome: c.name || '',
    negocio: c.name || '',
    nicho: meta.nicho || '',
    place_id: meta.place_id || '',
    horario_gmn: meta.horario_gmn || null,
    _source_metadata_raw: meta,
    avaliacoes: Number(meta.avaliacoes_gmn) || 0,
    cidade: meta.cidade || '',
    telefone: c.phone_number || '',
    telefone_normalizado: telNorm,
    status: wf01.status || '',
    etapa: wf01.etapa || '',
    bloqueado_wf01: wf01.bloqueado ? 'TRUE' : '',
    motivo_bloqueio_wf01: wf01.motivo_bloqueio || '',
    reservado_em: wf01.reservado_em || '',
    processando_em: wf01.processando_em || '',
    mensagem1_id: wf01.mensagem1_id || '',
    mensagem1_enviada_em: wf01.mensagem1_enviada_em || '',
    mensagem_enviada: wf01.mensagem_enviada || '',
    variante_mensagem: wf01.variante_mensagem || '',
    observacoes: wf01.observacoes || '',
    _custom_fields_raw: cf
  }
};

