const lead = $('Code - Detectar Robô (CRM)').item.json;
const atual = $input.first().json || {};
// custom_fields FRESCO do banco (o do lead normalizado é anterior ao envio e perderia a trava wf01)
const cf = (atual.custom_fields && typeof atual.custom_fields === 'object') ? atual.custom_fields : {};
const prev = cf.wf01 || {};
const nota = '[' + new Date().toISOString() + '] WF01: robo detectado apos envio. Motivo: ' + (lead.robo_motivo || '') + '. Texto recebido: ' + (lead.robo_texto_resposta || '');
const novo = Object.assign({}, cf, {
  wf01: Object.assign({}, prev, {
    status: 'robo_detectado',
    etapa: 'aguardando_humano',
    bloqueado: true,
    motivo_bloqueio: 'robo_detectado_resposta_automatica',
    observacoes: ((prev.observacoes || '') + '\n' + nota).trim()
  })
});
return [{ json: Object.assign({}, lead, { row_number: lead.id, patch_body: JSON.stringify({ custom_fields: novo }) }) }];

// Guarda de cadência do WF01: teto diário por fase, espaçamento, janela de horário e saúde do canal
const INICIO = '2026-10-07';
const FERIADOS = ['2026-10-12', '2026-11-02', '2026-11-20', '2026-12-25', '2027-01-01'];
const g = $json;
const agora = String(g.agora_brt || '');
const dia = agora.slice(0, 10);
const hh = parseInt(agora.slice(11, 13), 10);
const mm = parseInt(agora.slice(14, 16), 10);
const min = hh * 60 + mm;
const dow = (d) => new Date(d + 'T12:00:00Z').getUTCDay();
const util = (d) => dow(d) >= 1 && dow(d) <= 5 && !FERIADOS.includes(d);
let n = 0;
for (let t = new Date(INICIO + 'T12:00:00Z').getTime(); dia >= INICIO && new Date(t).toISOString().slice(0, 10) <= dia; t += 86400000) {
  if (util(new Date(t).toISOString().slice(0, 10))) n++;
}
// fases aprovadas: dias úteis 1-3 = 5/dia; 4-7 = 8/dia; a partir do 8 = 12/dia (20/dia só com aprovação do Hamilton)
let fase = n <= 7 ? { cap: 10, gap: 25 } : { cap: 12, gap: 25 };
// 07/10 (dia 1): já saíram 3 envios no teste da manhã; hoje saem mais 5, num ritmo mais curto (chip em uso normal há semanas)
if (dia === '2026-10-07') fase = { cap: 8, gap: 20 };
// 18h-19h30: janela extra só para negócios noturnos (pizzarias etc.); quem filtra o lead é o horário do GMN
const janela = (min >= 540 && min <= 710) || (min >= 840 && min <= 1070) || (min >= 1080 && min <= 1170);
const primeiroDoPeriodo = mm < 20 && (hh === 9 || hh === 14);
let ok = true, motivo = 'liberado', avisar = false;
if (dia < INICIO) { ok = false; motivo = 'antes_do_inicio'; }
else if (!util(dia)) { ok = false; motivo = 'dia_nao_util'; }
else if (!janela) { ok = false; motivo = 'fora_da_janela'; }
else if (g.canal_status !== 'WORKING') { ok = false; motivo = 'canal_' + g.canal_status; avisar = primeiroDoPeriodo; }
else if (Number(g.erros_envio_hoje || 0) >= 2) { ok = false; motivo = 'erros_de_envio_seguidos'; avisar = primeiroDoPeriodo; }
else if (Number(g.enviados_hoje || 0) >= fase.cap) { ok = false; motivo = 'teto_diario'; }
else if (g.minutos_desde_ultimo_envio !== null && g.minutos_desde_ultimo_envio !== undefined && Number(g.minutos_desde_ultimo_envio) < fase.gap) { ok = false; motivo = 'espacamento'; }
const NL = String.fromCharCode(10);
const texto_aviso = '⚠️ WF01 pausado pelo guarda de cadência' + NL + NL + 'Motivo: ' + motivo + NL + 'Canal: ' + g.canal_status + NL + 'Envios hoje: ' + g.enviados_hoje + '/' + fase.cap + NL + 'Erros de envio hoje: ' + g.erros_envio_hoje + NL + 'Dia útil da cadência: ' + n + NL + NL + 'Nada foi enviado. Verifique o canal antes de liberar.';
return [{ json: Object.assign({}, g, { ok, motivo, avisar, cap: fase.cap, gap: fase.gap, dia_util_n: n, texto_aviso }) }];

// consulta feita na hora do envio: junta o horário do GMN (Places API) ao lead e atualiza o cache em contacts.source_metadata.horario_gmn
const lead = $('GMN - Pegar 1º da Fila').first().json;
const r = $json || {};
const roh = r.regularOpeningHours || null;
const erro = r.error ? String((r.error && r.error.message) || r.error) : '';
const horario = { periods: (roh && roh.periods) || [], descricao: (roh && roh.weekdayDescriptions) || [], utc_offset_min: r.utcOffsetMinutes ?? null, fonte: 'places_v1', buscado_em: new Date().toISOString() };
const meta = Object.assign({}, lead._source_metadata_raw || {}, { horario_gmn: horario });
// se a consulta falhar, segue com o horário já salvo (WF00 ou consulta anterior); sem nenhum, decide pelo nicho
return { json: Object.assign({}, lead, { horario_gmn: erro ? (lead.horario_gmn || null) : horario, gmn_resposta_ok: !erro, gmn_erro: erro, patch_body: JSON.stringify({ source_metadata: meta }) }) };

